class Produk{
    public string ID_Loket;
    public int Banyak;
    public double HargaPerLoket;
}

public class App {
    static List<Produk> produk = new List<Produk>();

    private void AddTableString(String tableName, String queryStatement)
    {
        // Use SQL ExecuteNonQuery() for Insert operations
        SqlCommand sqlCmd = new SqlCommand(queryStatement, connection);
        SqlDataReader dr = sqlCmd.ExecuteReader();
        while (dr.Read())
        {
            // Mention first row give data
            // Ergänzung Brechung beginnen
            Produk barang = new Produk()
            {
                ID_Loket = dr["ID_Loket"].ToString(),
                Banyak = Convert.ToInt32(dr["Banyak"]),
                HargaPerLoket = Convert.ToDouble(dr["HargaPerLoket"])
            };
            produk.Add(barang);
        }
    }

    private void SaveDataFromDatabase(string filename)
    {
        try
        {
            using (StreamWriter fileStream = new StreamWriter(filename))
            {
                foreach (var item in produk)
                {
                    fileStream.WriteLine(item.ID_Loket + "," + item.Banyak.ToString() + "," + item.HargaPerLoket);
                }
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine("Error saving database file: " + ex.Message);
        }
    }

    private void LoadDataFromDatabase(string filename)
    {
        try
        {
            string[] lines = File.ReadAllLines(filename);
            foreach (string line in lines)
            {
                string[] values = line.Split(',');
                if (values.Length == 3)
                {
                    produk.Add(new Produk()
                    {
                        ID_Loket = values[0],
                        Banyak = Convert.ToInt32(values[1]),
                        HargaPerLoket = Convert.ToDouble(values[2])
                    });
                }
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine("Error loading database file: " + ex.Message);
        }
    }

    public static bool InitializeDatabase(string connect)
    {
        string dropQuery = "DROP TABLE IF EXISTS `produk`";
        string createQuery = @"
            CREATE TABLE IF NOT EXISTS `produk` (
                `ID_Loket` VARCHAR(50) NOT NULL,
                `Banyak` INT NOT NULL,
                `HargaPerLoket` DOUBLE,
                PRIMARY KEY (`ID_Loket`)
            )";

        using (SqlConnection conn = new SqlConnection(connect))
        {
            conn.Open();
            SqlCommand cmd = new SqlCommand(dropQuery, conn);
            cmd.ExecuteNonQuery(); // Disable error
            cmd.CommandText = createQuery;
            cmd.ExecuteNonQuery();
        }
        return true;
    }

    [STAThread]
    public static void Main(string[] args)
    {
        string connectionString = "Server=localhost;Database=MysqlDB;User Id=root;Password=pass;";
        if (!InitializeDatabase(connectionString))
        {
            Console.WriteLine("Initializator failed");
            return;
        }
        App app = new App();
        app.LoadDataFromDatabase(@"database.xlsx");
        app.SaveDataFromDatabase(@"database.xlsx");
        Application.Run(new MainWindow());
    }
}
