import 'package:flutter/material.dart';

class GuestDate extends StatefulWidget {
  const GuestDate({Key? key}) : super(key: key);

  @override
  _GuestDateState createState() => _GuestDateState();
}

class _GuestDateState extends State<GuestDate> {
  final List<String> startDateOptions = ['19', '20', '21'];
  final List<String> endDateOptions = ['18', '19', '20'];
  final List<String> datesSelected = [];

  void _selectStartDate(String date) {
    setState(() {
      datesSelected.add(date);
    });
  }

  void _selectEndDate(String date) {
    setState(() {
      datesSelected.add(date);
    });
  }

  void _clearDates() {
    setState(() {
      datesSelected.clear();
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Select Dates')),
      body: Column(
        children: [
          Padding(
            padding: EdgeInsets.all(8.0),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: [
                Text("Start Date"),
                DropdownButton<String>(
                  items: startDateOptions.map((String option) {
                    return DropdownMenuItem<String>(
                      value: option,
                      child: Text(option),
                    );
                  }).toList(),
                  onChanged: (_void Function(String)? value) => setState(() {
                    _selectStartDate(value!);
                  }),
                ),
                Text("End Date"),
                DropdownButton<String>(
                  items: endDateOptions.map((String option) {
                    return DropdownMenuItem<String>(
                      value: option,
                      child: Text(option),
                    );
                  }).toList(),
                  onChanged: (_void Function(String)? value) => setState(() {
                    _selectEndDate(value!);
                  }),
                )
              ],
            ),
          ),
          Expanded(
            child: Padding(
              padding: EdgeInsets.all(8.0),
              child: ListView.builder(
                itemCount: datesSelected.length,
                itemBuilder: (context, index) {
                  String date = datesSelected[index];
                  return ListTile(
                    title: Text(date),
                    trailing: IconButton(
                      icon: Icon(Icons.remove_circle),
                      onPressed: () {
                        setState(() {
                          datesSelected.removeAt(index);
                        });
                      },
                    ),
                  );
                },
              ),
            ),
          ),
          Container(
            width: double.infinity,
            margin: EdgeInsets.symmetric(vertical: 16),
            child: RaisedButton(
              color: Colors.blue[100],
              child: Text('OK'),
              onPressed: () {
                // Do something with selected dates
                setState(() {
                  _clearDates();
                });
