	struct IncrementalRatioStrategy {
    final private double[] intake;

    /* Weather helper */
    final private double[] coolerOutput;

    public IncrementalRatioStrategy(double[] intake, double[] output) {
        this.intake = intake;
        this.coolerOutput = output;
    }

    @Override
    public int update() {
        int iteration = 0;

        while(iteration <= intake.length && iteration <= coolerOutput.length) {

            if(intake[iteration] != coolerOutput[iteration]) {
                refresh(); //$result.postValue(true);
                break;
            } else {
                iteration++;
            }
        }

        return iteration;
    }

    private void refresh() {
        long buffersTotal = intake.length * 1000;
        long buffersFree = availableMemory();

        if(buffersTotal > buffersFree) {
            throw new RuntimeException(" Not enough memory to continue processing.");
        }
    }

    private long availableMemory() {
        long free = Runtime.getRuntime().freeMemory();
        long used = Runtime.getRuntime().totalMemory() - free;
        return used;
    }

}




