import 'package:flutter/material.dart';

class GuestDate extends StatefulWidget {
  const GuestDate({Key? key}) : super(key: key);

  @override
  _GuestDateState createState() => _GuestDateState();
}

class _GuestDateState extends State<GuestDate> {
  int selectedIndex = 0;
  bool isSuccess = true;

  void _showDialog(BuildContext context, String title) async {
    await showDialog(
      context: context,
      builder: (context) {
        return AlertDialog(
          title: Text(title),
          content: Text("Confirm this action?"),
          actions: [
            ElevatedButton(onPressed: () { Navigator.pop(context); }, child: Text("Cancel")),
            ElevatedButton(
              onPressed: () {
                setState(() {
                  if (isSuccess) {
                    setState(() {
                      isSuccess = false;
                    }
                  } else {
                    setState(() {
                      isSuccess = true;
                    }
                  }
                });
              },
              child: Text(isSuccess ? "OK" : "Cancel"),
            ),
          ],
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text("Select Date")),
      body: Column(children: [
        Expanded(child: ListView.builder(
          itemCount: 3,
          itemBuilder: (BuildContext context, index) {
            return ListTile(
              onTap: () {
                setState(() {
                  selectedIndex = index;
                });
              },
              leading: Icon(Icons.date_range),
              title: Text("Day ${index + 1}"),
              trailing: selectedIndex == index
                  ? Icon(Icons.check_box_selected)
                  : Icon(Icons.check_box_outline_blank),
            );
          }),
        ), 
        SizedBox(height: 16),
        ElevatedButton(
          style: ButtonStyle(
            backgroundColor: MaterialStateProperty.all<Color>(Colors.blue),
            foregroundColor: MaterialStateProperty.all<Color>(Colors.white),
          ),
          onPressed: () {
            if (selectedIndex != 0 && selectedIndex != 2) {
              _showDialog(context, "Date Selection");
            }
          },
          child: Text('Select Date'),
        ),
      ]),
    );
  }
}
```

