class Satuan{
    public int IdSatuan { get;set; }
    public string NamaSatuan { get;set; }
    public string NoCode { get;set; }
    public int KuantitasSatuan { get;set; } 
}

public class ControllerSale {
    private readonly IDbContextFactory<AppDbContext> _context;

    public ControllerSale(IDbContextFactory<AppDbContext> context){
        _context = context;
    }

    [Route("sales")] // For POST request
    [HttpPost]
    public async Task<IActionResult> Sale([FromBody] RequestSales request) => await HandleSale(request);

    private async Task<IActionResult> HandleSale(RequestSales request){
        var db = await _context.CreateAsync();

        if (request.ModelId != null) {
            var model = await db.Products.FindAsync(request.ModelId);
            if(model == null) return NotFound(); 

            var resultSatuan = new List<Satuan>();
            foreach(var satuanModel in request.satuanModels) {
                resultSatuan.Add(new Satuan() {
                    IdSatuan = satuanModel.IdSatuan,
                    NamaSatuan = satuanModel.NamaSatuan,
                    NoCode = satuanModel.NoCode,
                    KuantitasSatuan = satuanModel.KuantitasSatuan
                });
            }

            var inventoryCheck = await db.Stoks.FindAsync(model.ID, request.UserID); // Check stock for the product
            if(inventoryCheck == null || !inventoryCheck.HasValue) {
                return BadRequest("Product not found");
            }

            // Update stock
            inventoryCheck.Stok -= request.kuantitas;

            if(inventoryCheck.Stok < 0) {
                return BadRequest("Stock unavailable");
            }

            db.Entry(inventoryCheck).State = EntityState.Modified;
            await db.SaveChangesAsync();
            return Ok("Success");
        } else {
            return BadRequest("Invalid model ID");
        }
    }
}

using System;
using Microsoft.AspNetCore.Mvc;
using UnityEngine;


[ApiController]
[Route("[controller]")]
public class SalesController : ControllerBase {

    private readonly IProductsService _productsService;
    private readonly ILogger<HomeController> _logger;

    public SalesController(IProductsService productsService, ILogger<HomeController> logger) {
        _productsService = productsService;
        _logger = logger;
    }

    [HttpGet("items")]
    public IActionResult GetItems() {
        var items = _productsService.GetItems().ToList();
        return Ok(items);
    }

    [HttpDelete("{id}")]
    public IActionResult DeleteItem(int id) {
        bool deleted = _productsService.DeleteItem(id);
        if (!deleted) return NotFound();
        return Ok("Deleted!");
    }

    [HttpPost]
    public IActionResult AddItem(SalesItem item) {
        int success = _productsService.AddItem(item);
        if(success <= 0) return Conflict();

        return CreatedAtAction("GetItem", new { id = item.ItemID }, item);
    }
}

