function block_transposed(args) {
    const arr = [...args];
    let rows = [];
    let col_count;
    while (arr.length) {
        // Take the first row
        let col_slice = [];
        for (let i = 0; i < arr.length; i++) {
            col_slice.push(arr.pop());
        }
        let fixed_col_count = Math.max(...col_slice.map(i => i.length));
        rows.push(col_slice);

        // Add padding to fill columns
        for (let col = 0; col < fixed_col_count; col++) {
            arr.unshift(['']);
        }
    }
    return rows;
}

